// keys: "Leb" DELETE "ap" ENTER "y"
// expect: exit 1
// screen: 0 Name? Leap
// screen: 1 Hello, Leap!
char buf[11];
int main(void)
{
    cls();
    print("Name? ");
    gets(buf, sizeof buf);
    printf("Hello, %s!\n", buf);
    return getkey() == 'y';
}
